import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.annotation.WebServlet;
import java.io.IOException;
import java.io.PrintWriter;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private Connection getConnection() throws Exception {
        String url = System.getenv("JDBC_URL") != null ? 
            System.getenv("JDBC_URL") : "jdbc:postgresql://db:5432/analytics";
        String user = System.getenv("DB_USER") != null ? System.getenv("DB_USER") : "app_user";
        String pass = System.getenv("DB_PASS") != null ? System.getenv("DB_PASS") : "changeme";
        return DriverManager.getConnection(url, user, pass);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws IOException {
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");
        String department = req.getParameter("dept");

        if (sortCol == null) sortCol = "created_at";
        if (direction == null) direction = "DESC";

        // Validate direction to prevent injection there
        if (!direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC")) {
            direction = "DESC";
        }

        // Build query - department uses parameterized query
        // sortCol is validated against allowlist... or is it?
        String query;
        if (isValidColumn(sortCol)) {
            query = "SELECT id, title, department, created_at, status FROM reports " +
                    "WHERE department = ? ORDER BY " + sortCol + " " + direction;
        } else {
            // Fallback: still uses the raw input in error logging path
            logInvalidSort(sortCol);
            query = "SELECT id, title, department, created_at, status FROM reports " +
                    "WHERE department = ? ORDER BY created_at " + direction;
        }

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(query)) {
            stmt.setString(1, department);
            ResultSet rs = stmt.executeQuery();

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append(String.format(
                    "  {\"id\": %d, \"title\": \"%s\", \"department\": \"%s\", " +
                    "\"created_at\": \"%s\", \"status\": \"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getString("department").replace("\"", "\\\""),
                    rs.getString("created_at"),
                    rs.getString("status").replace("\"", "\\\"")
                ));
                first = false;
            }
            json.append("\n]");
            out.print(json.toString());
        } catch (Exception e) {
            resp.setStatus(500);
            // Leak error details for debugging
            out.print("{\"error\": \"" + e.getMessage().replace("\"", "\\\"") + "\"}");
        }
    }

    private boolean isValidColumn(String col) {
        // BUG: allowlist check uses contains() on a concatenated string
        // rather than checking set membership. This allows injection via
        // substrings like "created_at--" or "id,extractvalue(1,concat(0x7e,version()))"
        String allowed = "id,title,department,created_at,status";
        return allowed.contains(col);
    }

    private void logInvalidSort(String col) {
        System.err.println("[WARN] Invalid sort column requested: " + col);
    }
}
